<?php include '../includes/public_header.php'; ?><?php include '../includes/public_navbar.php'; ?><div class="layout"><?php include '../includes/public_sidebar.php'; ?><main class="public-content learning-public-page"><section class="page-hero-compact"><span class="section-kicker">Gamificación</span><h1>Mis logros</h1><p>Reconocimientos obtenidos por completar formación y superar evaluaciones.</p><div class="learning-course-hero-meta"><span>🏅 <?php echo $obtenidos; ?> obtenidos</span><span>🔒 <?php echo max(0,count($logros)-$obtenidos); ?> por desbloquear</span></div></section><section class="content-section content-section-first"><?php if(!$logros): ?><div class="empty-state">Todavía no hay logros configurados.</div><?php else: ?><div class="learning-achievement-grid"><?php foreach($logros as $l): ?><article class="learning-achievement-card <?php echo $l['obtenido']?'is-earned':'is-locked'; ?>"><div class="learning-achievement-medal"><?php echo $l['obtenido']?learningH($l['icono']):'🔒'; ?></div><div><span class="learning-achievement-state"><?php echo $l['obtenido']?'DESBLOQUEADO':'POR DESBLOQUEAR'; ?></span><h3><?php echo learningH($l['nombre']); ?></h3><p><?php echo learningH($l['descripcion']); ?></p><?php if($l['obtenido']): ?><small>Obtenido el <?php echo learningH(date('d/m/Y',strtotime($l['fecha_obtenido']))); ?></small><?php elseif($l['curso']): ?><small>Curso requerido: <?php echo learningH($l['curso']); ?></small><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section></main></div><?php include '../includes/public_footer.php'; ?>
